// reset removes every group entry, for Builder.Reset.
func (b *marketDataRequest_groups) reset() {
	clear(b.noPartyIDsEntries)
	b.noPartyIDsEntries = b.noPartyIDsEntries[:0]
	clear(b.noMDEntryTypesEntries)
	b.noMDEntryTypesEntries = b.noMDEntryTypesEntries[:0]
	clear(b.noRelatedSymEntries)
	b.noRelatedSymEntries = b.noRelatedSymEntries[:0]
	clear(b.noTradingSessionsEntries)
	b.noTradingSessionsEntries = b.noTradingSessionsEntries[:0]
	clear(b.noMarketSegmentsEntries)
	b.noMarketSegmentsEntries = b.noMarketSegmentsEntries[:0]
}

// appendTo appends the message's other repeating groups to dst.
func (b *marketDataRequest_groups) appendTo(dst []fix.Field) []fix.Field {
	if len(b.noPartyIDsEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoPartyIDs, len(b.noPartyIDsEntries))
		for _, entry := range b.noPartyIDsEntries {
			dst = entry.appendTo(dst, marketDataRequest_NoPartyIDs_layout)
		}
	}
	if len(b.noMDEntryTypesEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoMDEntryTypes, len(b.noMDEntryTypesEntries))
		for _, entry := range b.noMDEntryTypesEntries {
			dst = entry.appendTo(dst, marketDataRequest_NoMDEntryTypes_layout)
		}
	}
	if len(b.noRelatedSymEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoRelatedSym, len(b.noRelatedSymEntries))
		for _, entry := range b.noRelatedSymEntries {
			dst = entry.appendTo(dst, marketDataRequest_NoRelatedSym_layout)
		}
	}
	if len(b.noTradingSessionsEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoTradingSessions, len(b.noTradingSessionsEntries))
		for _, entry := range b.noTradingSessionsEntries {
			dst = entry.appendTo(dst, marketDataRequest_NoTradingSessions_layout)
		}
	}
	if len(b.noMarketSegmentsEntries) > 0 {
		dst = fix.AppendCount(dst, TagNoMarketSegments, len(b.noMarketSegmentsEntries))
		for _, entry := range b.noMarketSegmentsEntries {
			dst = entry.appendTo(dst, marketDataRequest_NoMarketSegments_layout)
		}
	}
	return dst
}
